<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thiebapower · Gestion</title><link rel="stylesheet" href="/style.css"><main><h1>THIEBAPOWER</h1><p>Tableau de bord · location de batteries</p>
<section><h2>Activité</h2><div class="grid"><?php foreach($stats as $s):?><div class="metric"><strong><?=(int)$s['quantity']?></strong><span><?=htmlspecialchars($s['status'],ENT_QUOTES,'UTF-8')?></span></div><?php endforeach?><div class="metric"><strong><?=count($batteries)?></strong><span>Batteries enregistrées</span></div></div><h3>Dernières locations</h3><div class="scroll"><table><thead><tr><th>Référence</th><th>Client</th><th>Location</th><th>Caution</th><th>État</th><th>Date</th></tr></thead><tbody><?php foreach($rentals as $r):?><tr><td><?=htmlspecialchars($r['reference'])?></td><td><?=htmlspecialchars($r['customer_name'])?></td><td><?=number_format($r['rental_fee'])?> F</td><td><?=number_format($r['deposit'])?> F</td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section>
<section><h2>Modes d’intégration</h2><p>La sélection d’un mode configure l’environnement. Les paiements et la libération restent fermés jusqu’à la validation complète des API.</p><form method="post" action="/admin/modes"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><fieldset><legend>Paiement Pro</legend><label class="choice"><input type="radio" name="paiementpro_mode" value="sandbox" <?=$modes['paiementpro']==='sandbox'?'checked':''?>> Sandbox</label><label class="choice"><input type="radio" name="paiementpro_mode" value="production" <?=$modes['paiementpro']==='production'?'checked':''?>> Production</label><small>Sandbox configurée : <?=$ready['paiementpro_sandbox']?'oui':'non'?> · Production configurée : <?=$ready['paiementpro_production']?'oui':'non'?></small></fieldset><fieldset><legend>HeyCharge · option 3</legend><label class="choice"><input type="radio" name="heycharge_mode" value="simulation" <?=$modes['heycharge']==='simulation'?'checked':''?>> Simulation</label><label class="choice"><input type="radio" name="heycharge_mode" value="normal" <?=$modes['heycharge']==='normal'?'checked':''?>> Normal</label><small>Clé API configurée : <?=$ready['heycharge_normal']?'oui':'non'?></small></fieldset><button>Enregistrer les modes</button></form></section>
<section><h2>Tarifs de location</h2><form action="/admin/prices" method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><label>Location FCFA<input type="number" min="0" name="rental_fee" value="<?=(int)$prices['rental_fee']?>" required></label><label>Caution par défaut FCFA<input type="number" min="0" name="default_deposit" value="<?=(int)$prices['default_deposit']?>" required></label><label>Durée incluse en minutes<input type="number" min="1" name="duration_minutes" value="<?=(int)$prices['duration_minutes']?>" required></label><label>Pourcentage par heure supplémentaire<input type="number" min="0" max="100" name="late_percent" value="<?=(int)$prices['late_percent']?>" required></label><button>Enregistrer les tarifs</button></form></section>
<section><h2>Batteries</h2><form action="/admin/batteries" method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><label>Numéro de série<input name="serial" required></label><label>Caution spécifique FCFA (vide = valeur par défaut)<input name="deposit_override" type="number" min="0"></label><button>Ajouter ou modifier</button></form><ul><?php foreach($batteries as $b):?><li><?=htmlspecialchars($b['serial'])?> · <?=htmlspecialchars($b['status'])?> · caution <?=htmlspecialchars((string)($b['deposit_override']??'par défaut'))?></li><?php endforeach?></ul></section></main></html>
